});

function calculate_late_entry_and_early_exit(frm) {
    if (!frm.doc.shift) {
        frappe.msgprint(__('Please select a Shift first.'));
        return;
    }

    frappe.db.get_doc('Shift Type', frm.doc.shift).then(shift => {
        if (!shift.start_time || !shift.end_time) {
            frappe.msgprint(__('Shift Type is missing start or end time.'));
            return;
        }

        // Example values
        const date_str = frm.doc.attendance_date;
        datetime_str = `${date_str} ${shift.start_time}`;
        const work_start = new Date(datetime_str); 
        console.log("work_start" + datetime_str);

        datetime_str = `${date_str} ${shift.end_time}`;
        const work_end = new Date(datetime_str); 

        const inTimeStr = frm.doc.in_time;
        const outTimeStr = frm.doc.out_time;

        if (inTimeStr) {

            const inTime = frappe.datetime.str_to_obj(inTimeStr);

            const lateMinutes = Math.max((inTime - work_start) / 60000, 0);

            frm.set_value('custom_late_entry_in_minutes', Math.round(lateMinutes * 10) / 10);
        }

        if (outTimeStr) {
            const outTime = frappe.datetime.str_to_obj(outTimeStr);
            const earlyMinutes = Math.max((work_end - outTime) / 60000, 0);
            frm.set_value('custom_early_exit_in_minutes', Math.round(earlyMinutes * 10) / 10);
        }
    });
}

