frappe.ui.form.on('ocr', {
    refresh: function(frm) {
        // Add button only if attachment exists
        if (frm.doc.attachment) {
            frm.add_custom_button(

                __('Extract Text from Image'),    // Button label
                function() {
                    frm.trigger('extract_ocr');   // Trigger the OCR function
                },
                __('Actions')                    // Section name
            );
        } else {
            frm.add_custom_button(
                __('Upload Image First'),
                () => {
                    frappe.msgprint(__('Please attach an image before extracting text.'));
                },
                __('Actions')
            ).addClass('btn-secondary').prop('disabled', true);
        }
    },

    // Define the OCR action (triggered by button)
    extract_ocr: function(frm) {
        const file_url = frm.doc.attachment;

        if (!file_url) {
            frappe.msgprint(__("Please attach an image first"));
            return;
        }

        frappe.call({
            method: 'moi_app.api.extract_text_from_image',  // Your whitelisted method
            args: {
                file_url: file_url
            },
            freeze: true,
            freeze_message: __('Processing image with OCR...'),
            callback: function(r) {
                if (r.message && r.message.text !== undefined) {
                    const extracted_text = r.message.text.trim();

                    if (extracted_text) {
                        // Show success with extracted text
                        frappe.msgprint({
                            title: __('OCR: Text Extracted Successfully'),
                            indicator: 'green',
                            message: __('Arabic text has been extracted from the image.'),
                            secondary_message: `
                                <pre style="
                                    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
                                    background: #f8f9fa;
                                    padding: 12px;
                                    border-radius: 6px;
                                    border: 1px solid #ddd;
                                    max-height: 400px;
                                    overflow: auto;
                                    white-space: pre-wrap;
                                    line-height: 1.5;
                                ">
                                    ${frappe.utils.escape_html(extracted_text)}
                                </pre>
                            `
                        });

                        // Save extracted text to a field
                        frm.set_value('extracted_text', extracted_text);
                    } else {
                        frappe.msgprint(__('No text found in the image. Try a clearer image.'));
                    }
                } else {
                    frappe.msgprint(__('OCR failed: ') + (r.exc || 'Unknown error'));
                }
            }
        });
    }
});

// --- OPTIONAL: keep your custom list in an HTML field (if you added it) ---
function getTargetUrl(fileName, stamp, signautre) {
    const fileNameUri = encodeURIComponent(extract_filename_from_href(fileName));

    let url = `/media-editor/?path=${fileNameUri}`;
    if (stamp) url += `&stamp=${encodeURIComponent(extract_filename_from_href(stamp))}`;
    if (signautre) url += `&sign=${encodeURIComponent(extract_filename_from_href(signautre))}`;
    return url;
}

async function get_user_credentials() {
    try {
        const user = frappe.session.user;
        const { message } = await frappe.db.get_value('User', user, ['stamp', 'signature']);
        return {
            stamp: message?.stamp || '',
            signature: message?.signature || ''
        };
    } catch (error) {
        console.error('Failed to fetch user credentials:', error);
        return { stamp: '', signature: '' };
    }
}

async function render_media_links(frm) {
    const html = frm.get_field('media_links');
    if (!html) return;

    const files = (frm.attachments && frm.attachments.get_attachments)
        ? frm.attachments.get_attachments()
        : [];

    const items = files
        .filter(f => !f.is_private) // show only public files (adjust if needed)
        .map(f => {
            const fileUrl = (f.file_url || '').split('?')[0];
            const name = fileUrl.split('/').pop();
            const label = frappe.utils.escape_html(f.file_name || name);
            const targetUrl = getTargetUrl(name, stamp, signature);
            return `<li style="margin:4px 0">
        <a href="${targetUrl}" target="_blank" rel="noopener">${label}</a>
      </li>`;
        });

    html.$wrapper.html(
        items.length
            ? `<div><strong>Open in Media Editor</strong><ul style="padding-left:18px; list-style:disc">${items.join('')}</ul></div>`
            : `<div class="text-muted">No public attachments.</div>`
    );
}

// --- NEW: Hijack clicks on the sidebar attachments ---
function extract_filename_from_href(href) {
    try {
        if (!href) return null;
        const u = new URL(href, window.location.origin);

        // Public files like /files/abc.png
        if (u.pathname.startsWith('/files/')) {
            return u.pathname.split('/').pop();
        }

        // Private download endpoint: /api/method/...download_file?file_url=/private/files/abc.png
        if (u.pathname.includes('/api/method/frappe.utils.file_manager.download_file')) {
            const p = u.searchParams.get('file_url') || '';
            if (p) return p.split('/').pop();
        }

        // Fallback
        return href.split('/').pop().split('?')[0];
    } catch (e) {
        return null;
    }
}

async function bind_sidebar_redirect(frm) {
    if (frm._bound_media_redirect) return; // avoid double binding
    frm._bound_media_redirect = true;

    const { stamp, signature } = await get_user_credentials();

    // Delegate clicks from the form wrapper (survives re-renders)
    frm.$wrapper.on('click',
        '.form-sidebar .form-attachments a, .form-sidebar .attachments a',
        function (e) {
            console.log("clicking!!!");
            const href = this.getAttribute('href') || '';
            // Skip if no href (delete buttons etc.)
            if (!href || (!stamp && !sign)) return;

            // Treat private files normally (don’t hijack)
            const isPrivate = href.includes('/private/files/') || href.includes('download_file');
            if (isPrivate) return;
            e.preventDefault();
            window.open(getTargetUrl(href, stamp, signature), '_blank');
        }
    );
}

frappe.ui.form.on('Inbox', {
