// Separate function to avoid code duplication
function validate_custom_sham_cach(frm) {
    // Get the value
    let cach_value = frm.doc.custom_sham_cach;

    // Check if it's not empty
    if (cach_value) {
        // Check if it contains only digits AND is exactly 12 characters long
        if (!/^\d{12}$/.test(cach_value)) {
            // Show an error message
            frappe.throw(__("Sham Cach must contain exactly 12 digits."));
            // Clear the invalid value
            frm.set_value('custom_sham_cach', '');
        }
    }
    // If it's empty, no validation is needed (assuming empty is allowed)
    // If you want to enforce that it cannot be empty, add an else block here.
}

