// Centralized logic — reused everywhere
function handle_visitor_qr_code(frm) {
    const visitor_qr_code = frm.doc.visitor_qr_code;

    // Clear dependent fields
    frm.set_value('full_name', '');
    frm.set_value('gender', '');
    frm.set_value('nationality', '');
    frm.set_value('document_type', '');
    frm.set_value('document_number', '');
    frm.set_value('check_in', 0); // Uncheck checkbox
    if (frm.fields_dict.visitor) {
        frm.set_value('visitor', '');
    }

    if (!visitor_qr_code) return;

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Visitor_Reception',
            filters: { barcode: visitor_qr_code },
            fields: ['full_name', 'gender', 'nationality', 'document_type', 'document_number', 'name'],
            limit: 1
        },
        callback: function(r) {
            if (r.message && r.message.length > 0) {
                const v = r.message[0];
                
                // Set visitor data
                frm.set_value('full_name', v.full_name || '');
                frm.set_value('gender', v.gender || '');
                frm.set_value('nationality', v.nationality || '');
                frm.set_value('document_type', v.document_type || '');
                frm.set_value('document_number', v.document_number || '');
                
                // ✅ Check the checkbox (1 = checked, 0 = unchecked)
                frm.set_value('check_in', 1);
                
                // Set visitor link if field exists
                if (frm.fields_dict.visitor) {
                    frm.set_value('visitor', v.name);
                }
                
                // Show success message
                frappe.show_alert(__('تم تحميل بيانات الزائر بنجاح'), 'green');
                
                // Set focus to organization field after a short delay
                setTimeout(() => {
                    if (frm.fields_dict.organization_or_institution_youre_planning_to_visit) {
                        frm.fields_dict.organization_or_institution_youre_planning_to_visit.$input.focus();
                    }
                }, 300);
                
            } else {
                frappe.msgprint({
                    title: __('غير موجود'),
                    message: __('باركود غير صحيح'),
                    indicator: 'red'
                });
                frm.set_value('visitor_qr_code', '');
            }
        }
    });
}

frappe.ui.form.on('Visitors', {

    validate: function(frm) {
        // التحقق من الحقول المطلوبة قبل الحفظ
        if (!frm.doc.full_name ||
            !frm.doc.nationality ||
            !frm.doc.document_number ||
            !frm.doc.gender ||
            !frm.doc.visitor_qr_code ||
            !frm.doc.visitcardno) {

            frappe.msgprint(__('يرجى تعبئة جميع الحقول المطلوبة قبل الحفظ'));
            frappe.validated = false;
        }
    },

    check_in: function(frm) {
        if (frm.doc.check_in) {
            // Uncheck check_out to ensure mutual exclusion
            frm.set_value('check_out', 0);

            // Set current time to entry_time only if it's empty (to preserve original value)
            if (!frm.doc.entry_time) {
                frm.set_value('entry_time', frappe.datetime.now_datetime());
            }
        }
        // تم إزالة جزء المسح (else) للاحتفاظ بالقيمة القديمة

        // Hide exit_time only when check_in is checked
        frm.toggle_display('exit_time', !frm.doc.check_in);
    },

    check_out: function(frm) {
        if (frm.doc.check_out) {
            // Uncheck check_in to ensure mutual exclusion
            frm.set_value('check_in', 0);

            // Set current time to exit_time only if it's empty (to preserve original value)
            if (!frm.doc.exit_time) {
                frm.set_value('exit_time', frappe.datetime.now_datetime());
            }
        }
        // تم إزالة جزء المسح (else) للاحتفاظ بالقيمة القديمة

        // Hide entry_time only when check_out is checked
        frm.toggle_display('entry_time', !frm.doc.check_out);
    },

    refresh: function(frm) {
        // Ensure correct visibility on form load
        frm.toggle_display('exit_time', !frm.doc.check_in);
        frm.toggle_display('entry_time', !frm.doc.check_out);
    }
});

