            frm._item_code_initialized = true;
            // Your debounce logic here (from previous answer)
        }
    },
    item_name: function(frm) {
        if (!frm.doc.item_name) {
            return;
        }

        const item_name = frm.doc.item_name.trim();
        if (!item_name) return;

        // Fetch all items that start with this name + "-"
        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'Item',
                filters: {
                    item_code: ['like', `${item_name} %`]
                },
                fields: ['item_code'],
                limit_page_length: 1000
            },
            callback: function(r) {
                let max_num = 0;

                if (r.message && r.message.length > 0) {
                    r.message.forEach(item => {
                        const parts = item.item_code.split(' ');
                        if (parts.length >= 2) {
                            const lastPart = parts[parts.length - 1];
                            const num = parseInt(lastPart, 10);
                            if (!isNaN(num)) {
                                if (num > max_num) max_num = num;
                            }
                        }
                    });
                }

                const next_num = max_num + 1;
                const padded_num = String(next_num).padStart(4, '0');
                const new_item_code = `${item_name} ${padded_num}`;

                frm.set_value('item_code', new_item_code);
            }
        });

    },
    item_group: function(frm){
        if (!frm.doc.item_group){
            frm.set_value('asset_category', '');
            return;
        }
                // Step 1: Get Item Group from Item
        frappe.db.get_value('Item', frm.doc.item_code, 'item_group')
            .then(r => {
                const item_group = r.message?.item_group;
                if (!item_group) {
