                        const asset_category = parent_group && parent_group !== 'All Item Groups' 
                            ? parent_group 
                            : item_group;
                        console.log("asset_category" + asset_category+"parent_group" + parent_group);
                        // Step 3: Set Asset Category
                        if (asset_category) {
                            frm.set_value('asset_category', asset_category);
                        } else {
                            frm.set_value('asset_category', '');
                        }
                    });
            });
    }

});

