frappe.ui.form.on('Staffing Plan', {
    refresh: function(frm) {
        // Hide original button
        frm.page.clear_actions_menu();

        // Add custom button
        frm.add_custom_button(__('Get Job Requisitions (Filtered)'), function() {
            // Step 1: Prompt for Department
            frappe.prompt({
                fieldtype: 'Link',
                label: __('Department'),
                fieldname: 'department',
                options: 'Department',
                reqd: 0
            }, function(data) {
                const filters = {
                    company: frm.doc.company,
                    status: 'Open'
                };
                if (data.department) filters.department = data.department;

                // Step 2: Fetch requisitions
                frappe.call({
                    method: 'frappe.client.get_list',
                    args: {
                        doctype: 'Job Requisition',
                        filters: filters,
                        fields: ['name', 'designation', 'department', 'requested_by']
                    },
                    callback: function(r) {
                        if (!r.message || r.message.length === 0) {
                            frappe.msgprint(__('No matching job requisitions found.'));
                            return;
                        }

                        // Step 3: Enrich with full names
                        let promises = r.message.map(req => {
                            if (req.requested_by) {
                                return frappe.db.get_value('User', req.requested_by, 'full_name')
                                    .then(res => {
                                        req.full_name = res.message?.full_name || req.requested_by;
                                        return req;
                                    });
                            } else {
                                req.full_name = __('N/A');
                                return Promise.resolve(req);
                            }
                        });

                        Promise.all(promises).then(requisitions => {
                            // Step 4: Build options for selection
                            let options = requisitions.map(req => ({
                                value: req.name,
                                label: `${req.name} | ${req.designation} | ${req.department} | Requested by: ${req.full_name}`
                            }));

                            // Step 5: Show selection dialog
                            let d = new frappe.ui.Dialog({
                                title: __('Select Job Requisitions'),
                                fields: [
                                    {
                                        fieldname: 'selected',
                                        fieldtype: 'MultiSelectList',
                                        get_data: () => options
                                    }
                                ],
                                primary_action_label: __('Add Selected'),
                                primary_action: function() {
                                    let selected = d.get_value('selected');
                                    if (!selected || selected.length === 0) {
                                        frappe.msgprint(__('Please select at least one.'));
                                        return;
                                    }

                                    frm.clear_table('staffing_details');
                                    selected.forEach(name => {
                                        let req = requisitions.find(r => r.name === name);
                                        if (req) {
                                            let row = frm.add_child('staffing_details');
                                            row.designation = req.designation;
                                            row.department = req.department;
                                            row.number_of_positions = 1;
                                            row.job_requisition = req.name;
                                        }
                                    });
                                    frm.refresh_field('staffing_details');
                                    d.hide();
                                    frappe.msgprint(__('{0} requisition(s) added.', [selected.length]));
                                }
                            });
                            d.show();
                        });
                    }
                });
            }, __('Filter by Department'), __('Continue'));
        }, __('Actions'));
    }
});

