/*******************************************************
 *  1) CONFIG (Links to preload titles)
 *******************************************************/
const CONFIG = [
  {
    table: "committee_members",
    links: [
      { field: "member", doctype: "Employee", title_field: "employee_name" }
    ]
  },
  {
    table: "member_evaluations",
    links: [
      { field: "committee_member", doctype: "Employee", title_field: "employee_name" },
      { field: "question", doctype: "Question Panel", title_field: "question" } // <-- عدّلها لو يلزم
    ]
  }
];

/*******************************************************
 *  2) Link Title Cache Helpers
 *******************************************************/
function set_link_title_cache(doctype, name, title) {
  frappe._link_titles = frappe._link_titles || {};
  frappe._link_titles[doctype] = frappe._link_titles[doctype] || {};
  frappe._link_titles[doctype][name] = title;

  // احتياط لبعض الحالات
  frappe._link_titles[`${doctype}::${name}`] = title;
}

async function preload_titles(frm, table_field, link_field, doctype, title_field) {
  const rows = frm.doc[table_field] || [];
  const ids = [...new Set(rows.map(r => r[link_field]).filter(Boolean))];
  if (!ids.length) return;

  const existing = frappe._link_titles?.[doctype] || {};
  const missing = ids.filter(id => !existing[id]);
  if (!missing.length) return;

  const list = await frappe.db.get_list(doctype, {
    filters: { name: ["in", missing] },
    fields: ["name", title_field],
    limit: 9999
  });

  (list || []).forEach(d => {
    set_link_title_cache(doctype, d.name, d[title_field] || d.name);
  });
}

/*******************************************************
 *  3) Safe Preload Runner (NO grid.refresh override)
 *******************************************************/
function debounce(fn, wait = 120) {
  let t;
  return function (...args) {
    clearTimeout(t);
    t = setTimeout(() => fn.apply(this, args), wait);
  };
}

async function preload_for_table(frm, table_field) {
  const table_cfg = CONFIG.find(c => c.table === table_field);
  if (!table_cfg) return;

  for (const l of table_cfg.links) {
    await preload_titles(frm, table_field, l.field, l.doctype, l.title_field);
  }

  // هذا يكفي غالبًا لإظهار العنوان بدل الـ ID
  frm.refresh_field(table_field);

  // احتياط: لو الجريد ما يعيد الرندر بشكل كامل (بدون override)
  const grid = frm.fields_dict[table_field]?.grid;
  if (grid && typeof grid.refresh === "function") {
    grid.refresh();
  }
}

function setup_preload_triggers(frm) {
  frm.__preload_setup = frm.__preload_setup || false;
  if (frm.__preload_setup) return;
  frm.__preload_setup = true;

  frm.__schedule_preload = frm.__schedule_preload || {};
  CONFIG.forEach(c => {
    frm.__schedule_preload[c.table] = debounce(() => {
      const flag = `__preloading_${c.table}`;
      if (frm[flag]) return;
      frm[flag] = true;

      Promise.resolve()
        .then(() => preload_for_table(frm, c.table))
        .finally(() => { frm[flag] = false; });
    }, 80);
  });

  // Trigger عند إضافة/حذف صفوف child table (أحداث ثابتة في Frappe)
  CONFIG.forEach(c => {
    frm.on(`${c.table}_add`, () => frm.__schedule_preload[c.table]());
    frm.on(`${c.table}_remove`, () => frm.__schedule_preload[c.table]());
  });

  // Trigger عند تغيير قيمة link داخل أي صف (أثبت من مراقبة grid.refresh)
  CONFIG.forEach(c => {
    const grid = frm.fields_dict[c.table]?.grid;
    if (!grid) return;

    const child_doctype = grid.doctype;
    if (!child_doctype) return;

    frm.__child_link_hooks = frm.__child_link_hooks || {};
    const key = `${c.table}::${child_doctype}`;
    if (frm.__child_link_hooks[key]) return;
    frm.__child_link_hooks[key] = true;

    const handlers = {};
    c.links.forEach(l => {
      handlers[l.field] = function (frm, cdt, cdn) {
        // مجرد تغيير قيمة link -> نعمل preload للجدول
        frm.__schedule_preload[c.table]();
      };
    });

    frappe.ui.form.on(child_doctype, handlers);
  });
}

/*******************************************************
 *  4) Rules: Fields visibility/editability by member_type
 *******************************************************/
function apply_member_eval_rules(frm, cdt, cdn) {
  const row = locals[cdt][cdn];
  const grid = frm.fields_dict.member_evaluations?.grid;
  if (!grid) return;

  const grid_row = grid.get_row(cdn);
  if (!grid_row) return;

  const is_hr = (row.member_type === "HR");

  if (is_hr) {
    if (grid_row.toggle_display) {
      grid_row.toggle_display('question', true);
      grid_row.toggle_display('tquestion', false);
      grid_row.toggle_display('selected_option', true);
      grid_row.toggle_display('max_score', true);
    }

    if (grid_row.toggle_editable) {
      grid_row.toggle_editable('question', false);
      grid_row.toggle_editable('tquestion', false);
      grid_row.toggle_editable('selected_option', true);
      grid_row.toggle_editable('max_score', false);
      grid_row.toggle_editable('member_name', false);
    }

    // تنظيف قيم غير لازمة لـ HR
    if (row.tquestion) frappe.model.set_value(cdt, cdn, 'tquestion', null);
    return;
  }

  // Non-HR
  if (grid_row.toggle_display) {
    grid_row.toggle_display('question', false);
    grid_row.toggle_display('tquestion', true);
    grid_row.toggle_display('selected_option', false);
    // ملاحظة: هذا كان عندك toggle_editable للتعليق "إظهار"، تركناه مثل منطقك العام
  }

  if (grid_row.toggle_editable) {
    grid_row.toggle_editable('question', false);
    grid_row.toggle_editable('tquestion', true);
    grid_row.toggle_editable('selected_option', false);
    grid_row.toggle_editable('max_score', true);
    grid_row.toggle_editable('member_name', false);
  }

  // تنظيف قيم غير لازمة لغير HR
  if (row.question) frappe.model.set_value(cdt, cdn, 'question', null);
  if (row.selected_option) frappe.model.set_value(cdt, cdn, 'selected_option', null);
}

function apply_rules_for_all_rows(frm) {
  (frm.doc.member_evaluations || []).forEach(r => {
    apply_member_eval_rules(frm, r.doctype, r.name);
  });
}

/*******************************************************
 *  5) Interview (Parent) Script
 *******************************************************/
frappe.ui.form.on("Interview", {
  onload(frm) {
    setup_preload_triggers(frm);
  },

  refresh(frm) {
    setup_preload_triggers(frm);

    // 1) طبق القواعد
    apply_rules_for_all_rows(frm);

    // 2) preload titles فورًا (ليظهر الاسم بدل id بدون فتح سطر)
    setTimeout(() => {
      CONFIG.forEach(c => frm.__schedule_preload?.[c.table]?.());
    }, 0);
  },

  interview_round: async function(frm) {
    if (!frm.doc.interview_round) return;
    if (frm.__loading_round) return;
    frm.__loading_round = true;

    try {
      frm.clear_table('committee_members');
      frm.clear_table('member_evaluations');

      const r = await frappe.call({
        method: 'frappe.client.get',
        args: { doctype: 'Interview Round', name: frm.doc.interview_round }
      });

      const members = (r.message && r.message.committee_members) ? r.message.committee_members : [];
      if (!members.length) {
        frm.refresh_field('committee_members');
        frm.refresh_field('member_evaluations');
        return;
      }

      const hr_members = [];

      // 1) إضافة الأعضاء
      members.forEach(m => {
        let cm = frm.add_child('committee_members');
        cm.member = m.member;
        cm.member_type = m.member_type;
        cm.weight = m.weight;

        if (m.member_type === "HR") {
          hr_members.push(m.member);
        } else {
          let me = frm.add_child('member_evaluations');
          me.committee_member = m.member;
          me.member_type = m.member_type;
        }
      });

      frm.refresh_field('committee_members');

      // 2) إذا لا يوجد HR
      if (!hr_members.length) {
        frm.refresh_field('member_evaluations');
        apply_rules_for_all_rows(frm);

        // preload للعناوين
        CONFIG.forEach(c => frm.__schedule_preload?.[c.table]?.());
        return;
      }

      // 3) جلب أسئلة HR
      const q = await frappe.call({
        method: 'frappe.client.get_list',
        args: {
          doctype: 'Question Panel',
          filters: { member_type: "HR" },
          fields: ['name', 'max_score'],
          order_by: 'idx asc'
        }
      });

      let questions = q.message || [];
      if (!questions.length) {
        frm.refresh_field('member_evaluations');
        apply_rules_for_all_rows(frm);

        CONFIG.forEach(c => frm.__schedule_preload?.[c.table]?.());
        return;
      }

      // 4) إزالة التكرار
      const seen = new Set();
      questions = questions.filter(x => x.name && !seen.has(x.name) && (seen.add(x.name), true));

      // 5) توزيع الأسئلة على أعضاء HR
      const mCount = hr_members.length;
      const qCount = questions.length;
      const base = Math.floor(qCount / mCount);
      const remainder = qCount % mCount;

      let idx = 0;
      for (let i = 0; i < mCount; i++) {
        const take = base + (i < remainder ? 1 : 0);
        for (let j = 0; j < take; j++) {
          const question = questions[idx++];
          if (!question) break;

          let me = frm.add_child('member_evaluations');
          me.committee_member = hr_members[i];
          me.member_type = "HR";
          me.question = question.name;
          me.max_score = question.max_score;
        }
      }

      frm.refresh_field('member_evaluations');
      apply_rules_for_all_rows(frm);

      // ✅ أهم نقطة: بعد ما عبّينا الجداول، نعمل preload titles
      // ليظهر الاسم/السؤال بدل الـ ID بدون فتح السطر
      CONFIG.forEach(c => frm.__schedule_preload?.[c.table]?.());

    } finally {
      frm.__loading_round = false;
    }
  }
});

