function set_link_title_cache(doctype, name, title) {
  frappe._link_titles = frappe._link_titles || {};
  frappe._link_titles[doctype] = frappe._link_titles[doctype] || {};
  frappe._link_titles[doctype][name] = title;
  frappe._link_titles[`${doctype}::${name}`] = title;
}

async function preload_titles(frm, table_field, link_field, doctype, title_field) {
  const rows = frm.doc[table_field] || [];
  const ids = [...new Set(rows.map(r => r[link_field]).filter(Boolean))];
  if (!ids.length) return;
  const list = await frappe.db.get_list(doctype, {
    filters: { name: ["in", ids] },
