function fetchLocationForDialog() {
    const statusText = document.getElementById('location-status-text');
    const coordsDiv = document.getElementById('location-coords');

    if (!navigator.geolocation) {
        frappe.msgprint(__('Geolocation is not supported by your browser.'));
        return;
    }

    if (statusText) {
        statusText.textContent = 'Fetching...';
        statusText.style.color = 'blue';
    }

    navigator.geolocation.getCurrentPosition(
        function(position) {
            const lat = position.coords.latitude;
            const lng = position.coords.longitude;

            if (statusText) {
                statusText.textContent = __('✅ Location fetched');
                statusText.style.color = 'green';
            }
            if (coordsDiv) {
                coordsDiv.style.display = 'block';
                coordsDiv.textContent = `Lat: ${lat.toFixed(6)}, Lng: ${lng.toFixed(6)}`;
            }

            window._checkin_location = { lat, lng };

            frappe.show_alert({
                message: __('Location fetched successfully!'),
                indicator: 'green'
            });
        },
        function(error) {
            let errorMsg = 'Unable to fetch location: ';
            switch(error.code) {
                case error.PERMISSION_DENIED:
                    errorMsg += 'Permission denied. Please allow location access.';
                    break;
                case error.POSITION_UNAVAILABLE:
                    errorMsg += 'Location information unavailable.';
                    break;
                case error.TIMEOUT:
                    errorMsg += 'Request timed out.';
                    break;
                default:
                    errorMsg += error.message;
            }
            if (statusText) {
                statusText.textContent = '❌ ' + errorMsg;
                statusText.style.color = 'red';
            }
            delete window._checkin_location;
        },
        { enableHighAccuracy: true, timeout: 10000 }
    );
}

function submitCheckinViaDialog(values) {
    // Validate
    if (!values.employee) {
        frappe.msgprint(__('Please select an employee'));
        return;
    }

    // Prepare data
    let data = {
        doctype: 'Employee Checkin',
        employee: values.employee,
        time: values.datetime,
        log_type: values.log_type,
        device_id: 'Web Checkin',
        skip_auto_attendance: 0
    };

    // Add location if available
    if (window._checkin_location) {
        data.latitude = window._checkin_location.lat;
        data.longitude = window._checkin_location.lng;
    }

    // Submit
    frappe.call({
        method: 'frappe.client.insert',
        args: { doc: data },
        callback: function(response) {
            if (response.message) {
                const doc = response.message;
                frappe.msgprint({
                    title: __('✅ Success'),
                    indicator: 'green',
                    message: `
                        <b>Check-in recorded successfully!</b>
                        <br><br>
                        <b>Employee:</b> ${doc.employee}
                        <br>
                        <b>Time:</b> ${doc.time}
                        <br>
                        <b>Type:</b> ${doc.log_type}
                        ${doc.custom_latitude ? `<br><b>Location:</b> ${doc.custom_latitude}, ${doc.custom_longitude}` : ''}
                        <br><br>
                        <b>Checkin ID:</b> ${doc.name}
                    `
                });

                delete window._checkin_location;

// Refresh the list view - FIXED: Use the correct method
                if (frappe.listview_settings['Employee Checkin'] && 
                    frappe.listview_settings['Employee Checkin'].listview) {
                    // Method 1: Refresh using the stored listview reference
                    frappe.listview_settings['Employee Checkin'].listview.refresh();
                } else {
                    // Method 2: Refresh using frappe's built-in method
                    frappe.ui.toolbar.clear_cache();

                    // Method 3: Reload the page (works but less elegant)
                    // location.reload();

                    // Method 4: Refresh the current view
                    frappe.get_route();
                }

                // Close the dialog
                if (checkin_dialog) {
                    checkin_dialog.hide();
                    checkin_dialog = null;
                }
            }
        },
        error: function(err) {
            frappe.msgprint({
                title: __('❌ Error'),
                indicator: 'red',
                message: err.message || __('Failed to record check-in. Please try again.')
            });
        }
    });
}

// ==== Utility Functions (unchanged) ====
function loadSheetJS(callback) {
    if (window.XLSX) return callback();
    const script = document.createElement('script');
    script.src = 'https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js';
    script.onload = callback;
    script.onerror = () => frappe.msgprint(__('Failed to load Excel library'));
    document.head.appendChild(script);
}

function loadJSZipAndFileSaver(callback) {
    if (window.JSZip && window.saveAs) return callback();
    loadScript('https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js', () =>
        loadScript('https://cdnjs.cloudflare.com/ajax/libs/FileSaver.js/2.0.5/FileSaver.min.js', callback)
    );
}

function loadScript(src, callback) {
    const script = document.createElement('script');
    script.src = src;
    script.onload = callback;
    script.onerror = () => frappe.throw(__('Failed to load: ') + src);
    document.head.appendChild(script);
}

