function calculate_hours(frm, cdt, cdn) {
    // cdt هو اسم الـ Child Table
    // cdn هو رقم السطر (Row ID)
    let row = locals[cdt][cdn];
    
    if (row.from_time && row.to_time) {
        // نستخدم مكتبة moment المدمجة في النظام لحساب الوقت بدقة
        let start = moment(row.from_time, "HH:mm:ss");
        let end = moment(row.to_time, "HH:mm:ss");
        
        // حساب الفرق بالدقائق
        let duration = moment.duration(end.diff(start));
        let hours = duration.asHours();
        
        // تحديث الحقل في السطر الحالي
        frappe.model.set_value(cdt, cdn, 'total_hours', hours.toFixed(2));
    }
}

