function check_all_items_are_assets_sync(frm) {
    if (!frm.doc.items || frm.doc.items.length === 0) {
        frm.set_value('custom_is_all_items_are_assets', 0);
        return;
    }

    let all_are_assets = true;

    for (let i = 0; i < frm.doc.items.length; i++) {
        let item = frm.doc.items[i];

        if (item.item_code) {
            // Check if the item is already in the cache
            if (item.is_fixed_asset !== undefined) {
                if (!item.is_fixed_asset) {
                    all_are_assets = false;
                    break;
                }
            } else {
                // Use synchronous call (use with caution)
                let is_fixed_asset = frappe.db.get_value('Item', item.item_code, 'is_fixed_asset');
                if (is_fixed_asset && !is_fixed_asset.is_fixed_asset) {
                    all_are_assets = false;
                    break;
                }
            }
        } else {
            all_are_assets = false;
            break;
        }
    }

    frm.set_value('custom_is_all_items_are_assets', all_are_assets ? 1 : 0);
}

