function load_workflow_steps(frm) {
    frappe.call({   
        method: 'moi_app.utils.get_workflow_states',
        args: {
            workflow_name: "Material Request Workflow",
            docname: frm.doc.name
        },
        callback: function(state_response) {
            // FIXED: Changed 'response.message' to 'state_response.message'
            if (state_response.message) {
                let transitions = state_response.message;
                let states = transitions || [];

                let current_state = frm.doc.workflow_state;

                // Generate HTML for progress steps
                let html = generate_workflow_steps_html(states, current_state);

                // Update the HTML field in the DETAIL tab
                if (frm.fields_dict.custom_progress_bar) {
                    frm.fields_dict.custom_progress_bar.html(html);
                    frm.refresh_field('custom_progress_bar');
                } else {
                    console.warn('custom_progress_bar field not found. Please add it to Material Request form.');
                    // Fallback: Show in dashboard if field doesn't exist
                    show_in_dashboard_fallback(frm, html);
                }
            } else {
                console.log('No workflow states found for Material Request');
                let no_workflow_html = '<div class="alert alert-info">No workflow states configured for Material Request</div>';
                if (frm.fields_dict.custom_progress_bar) {
