            let error_html = '<div class="alert alert-danger">Error loading workflow: ' + (err.message || 'Unknown error') + '</div>';
            if (frm.fields_dict.custom_progress_bar) {
                frm.fields_dict.custom_progress_bar.html(error_html);
            }
        }
    });
}

function generate_workflow_steps_html(states, current_state) {
    if (!states || states.length === 0) {
        return '<div class="alert alert-info">No workflow states configured</div>';
    }

    let current_index = -1;
    let state_names = [];
    let transitions_map = {};

    // Handle the data structure: [state, next_states]
    states.forEach((item, index) => {
        // Check if item is an array
        if (Array.isArray(item)) {
            let state = item[0];
            let next_states = item[1] || [];

            if (state) {
                state_names.push(state);
                transitions_map[state] = next_states;

                if (state === current_state) {
                    current_index = index;
                }
            }
        } else if (typeof item === 'object' && item.state) {
            // Handle object format if needed
            state_names.push(item.state);
            transitions_map[item.state] = item.next_states || [];
            if (item.state === current_state) {
                current_index = index;
            }
        }
    });

    // If current state not found, try to find it in state_names
    if (current_index === -1 && current_state) {
        current_index = state_names.indexOf(current_state);
    }

    let percentage = calculate_percentage(current_index, state_names.length);
    let title = current_state || (state_names[0] || 'Draft');

    let html = `
        <div class="workflow-progress-container detail-tab-workflow">
            <div class="workflow-steps-container">
                <div class="workflow-steps">
    `;

    state_names.forEach((state, index) => {
        let status_class = '';
        let icon = '';
        let step_status = '';
        let has_branches = transitions_map[state] && transitions_map[state].length > 1;
        let next_states_text = has_branches ? `↳ ${transitions_map[state].join(', ')}` : '';

        // Check if this is a rejection state
        let isRejection = state.toLowerCase().includes('reject') || 
                          state.toLowerCase().includes('rejcted');
        let rejection_class = isRejection ? 'rejected' : '';

        if (current_index >= index && current_index !== -1) {
            status_class = 'completed';
            icon = isRejection ? '⚠️' : '⏺';
            step_status = __('Completed');
        }
        if (current_state === state) {
            status_class = isRejection ? 'activerejected' : 'activeapproved';
            icon = isRejection ? '⚠️' : '⏺';
            step_status = __('Current');
        }
        if ((current_index < index || current_index === -1) && current_state !== state) {
            status_class = 'pending';
            icon = '○';
            step_status = '';
        }

        html += `
            <div class="workflow-step ${status_class} ${rejection_class}">
                <div class="step-icon">${icon}</div>
                <div class="step-content">
                    <div class="step-name">${__(state)}</div>
                    <div class="step-status ${status_class} ${rejection_class}">${step_status}</div>
                </div>
            </div>
        `;

        if (index < state_names.length - 1) {
            let line_class = (current_index > index && current_index !== -1) ? 'completed-line' : '';
            // Check if the next state is a rejection for line styling
            let next_state = state_names[index + 1];
            let next_is_rejection = next_state.toLowerCase().includes('reject') || 
                                    next_state.toLowerCase().includes('rejcted');
            let rejection_line_class = next_is_rejection ? 'rejected-line' : '';
            html += `<div class="step-connector ${line_class} ${rejection_line_class}"></div>`;
        }
    });

    html += `
                </div>
            </div>
    `;

    return html;
}

function calculate_percentage(current_index, total_steps) {
    if (total_steps === 0) return 0;
    if (current_index < 0) return 0;
    return Math.round(((current_index + 1) / total_steps) * 100);
}

