frappe.ui.form.on('Employee', {
    before_save: function(frm) {
        if (!frm.doc.first_name || !frm.doc.last_name) return;

        // Remove spaces for comparison
        function clean(name) {
            return name ? name.trim().replace(/\s/g, '') : '';
        }

        let newFirst = clean(frm.doc.first_name);
        let newMiddle = clean(frm.doc.middle_name);
        let newLast = clean(frm.doc.last_name);

        let isDuplicate = false;
        let duplicateName = '';

        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'Employee',
                filters: { name: ['!=', frm.doc.name || ''] },
                fields: ['first_name', 'middle_name', 'last_name', 'employee_name']
            },
            async: false,
            callback: function(r) {
                if (r.message) {
                    for (let emp of r.message) {
                        let existFirst = clean(emp.first_name);
                        let existMiddle = clean(emp.middle_name);
                        let existLast = clean(emp.last_name);

                        if (newFirst === existFirst && newLast === existLast && newMiddle === existMiddle) {
                            isDuplicate = true;
                            duplicateName = emp.employee_name;
                            break;
                        }
                    }
                }
            }
        });

        if (isDuplicate) {
            frappe.msgprint(`⚠️ Employee "${duplicateName}" already exists with the same name.`);
            frappe.validated = false;
        }
    }
});

