// 3. Helper Function to Fetch Data
function fetch_and_set_specifications(frm, asset_id, cdt, cdn) {
    frappe.show_alert({
        message: __('Fetching specifications for asset: {0}', [asset_id]),
        indicator: 'orange'
    });

    frappe.call({
        method: 'moi_app.utils.fetch_asset_description_by_id',
        args: { asset_id: asset_id },
        callback: function(response) {
            if (response.message) {
                // frappe.model.set_value automatically refreshes the grid UI 
                frappe.model.set_value(cdt, cdn, 'specifications', response.message);

                frappe.show_alert({
                    message: __('✅ Specifications loaded for {0}', [asset_id]),
                    indicator: 'green'
                });
            } else {
                frappe.show_alert({
                    message: __('⚠️ No specifications found for {0}', [asset_id]),
                    indicator: 'orange'
                });
                frappe.model.set_value(cdt, cdn, 'specifications', '');
            }
        },
        error: function(error) {
            frappe.show_alert({
                message: __('❌ Failed to fetch specifications for {0}', [asset_id]),
                indicator: 'red'
            });
            console.error(error);
        }
    });
}

