            frappe.msgprint(__('قيمة قراءة العداد السابقة يجب أن تكون أكبر من 10,000 ولا تتجاوز 7 خانات.'));
            frappe.validated = false;
        }
        if (frm.doc.current_request && !is_valid_reading(frm.doc.current_request)) {
            frappe.msgprint(__('قيمة قراءة العداد الحالية يجب أن تكون أكبر من 10,000 ولا تتجاوز 7 خانات.'));
            frappe.validated = false;
        }
    }
});

// دالة مخصصة لفحص الشروط (أكبر من 10000 وأقصى حد 7 خانات)
function is_valid_reading(value) {
    let num = flt(value);
    // تحويل الرقم لنص لمعرفة عدد الخانات بدون الفواصل العشرية
    let length = Math.floor(num).toString().length; 
    
    return num > 10000 && length <= 7;
}

function validate_and_calculate(frm, field_name) {
    let val = frm.doc[field_name];
    
    if (val) {
        if (!is_valid_reading(val)) {
            frappe.msgprint({
                title: __('خطأ في الإدخال'),
                indicator: 'red',
                message: __('يجب أن يكون الرقم أكبر من 10,000 ولا يتجاوز 7 خانات (أقل من 10,000,000)')
            });
            // تفريغ الحقل لإجبار المستخدم على إعادة الإدخال بشكل صحيح
            frm.set_value(field_name, '');
            frm.set_value('distance_difference', 0);
            return;
        }
    }
    // إذا كان الإدخال سليماً، نقوم بحساب الفرق
    calculate_difference(frm);
}

function calculate_difference(frm) {
    if (frm.doc.current_request && frm.doc.previous_request) {
        let diff = flt(frm.doc.current_request) - flt(frm.doc.previous_request);
        
        // إذا كانت النتيجة سالبة (العداد الحالي أصغر من السابق)
        if (diff < 0) {
            frappe.msgprint(__('تنبيه: قراءة العداد الحالي لا يمكن أن تكون أقل من القراءة السابقة.'));
            frm.set_value('distance_difference', 0);
        } else {
            frm.set_value('distance_difference', diff);
        }
    } else {
        frm.set_value('distance_difference', 0);
    }
}

