function mp_render_preview(frm) {
  const field = frm.fields_dict[MP_CFG.preview_html_field];
  if (!field || !field.$wrapper) return;

  const rows = frm.doc[MP_CFG.child_table_field] || [];

  if (!rows.length) {
    field.$wrapper.html(`
      ${mp_get_styles()}
      <div class="mp-empty-box">لا توجد مواد إعلامية مضافة بعد.</div>
    `);
    return;
  }

  let html = mp_get_styles();
  html += `<div class="mp-preview-wrap">`;

  rows.forEach((row, index) => {
    html += mp_build_material_card(row, index);
  });

  html += `</div>`;
  field.$wrapper.html(html);

  field.$wrapper.find(".mp-open-row").on("click", function () {
    const cdn = $(this).attr("data-cdn");
    mp_open_child_row(frm, cdn);
  });

  field.$wrapper.find(".mp-toggle-platforms").on("click", function () {
    const cdn = $(this).attr("data-cdn");
    const details = field.$wrapper.find(`.mp-platforms[data-cdn="${cdn}"]`);
    const icon = $(this).find(".mp-toggle-icon");

    details.slideToggle(180);
    icon.text(icon.text() === "⌄" ? "⌃" : "⌄");
  });
}

function mp_build_material_card(row, index) {
  const title = mp_get_first_value(row, MP_CFG.title_fields) || `المادة الإعلامية ${index + 1}`;
  const type = mp_get_first_value(row, MP_CFG.type_fields) || "-";

  let totals = {
    views: 0,
    comments: 0,
    shares: 0,
    likes: 0,
    engagement_total: 0
  };

  let platforms_html = "";

  MP_CFG.platforms.forEach((p) => {
    const link = row[p.link_field];
    const summary = mp_parse_json(row[p.summary_field]);

    if (!link && !summary) return;

    const metrics = summary && summary.metrics ? summary.metrics : {};

    totals.views += Number(metrics.views || 0);
    totals.comments += Number(metrics.comments || 0);
    totals.shares += Number(metrics.shares || 0);
    totals.likes += Number(metrics.likes || 0);
    totals.engagement_total += Number(metrics.engagement_total || 0);

    platforms_html += mp_build_platform_line(p, link, summary);
  });

  if (!platforms_html) {
    platforms_html = `<div class="mp-muted">لا توجد روابط أو إحصائيات منصات لهذه المادة.</div>`;
  }

  return `
    <div class="mp-card">
      <div class="mp-card-head">
        <div class="mp-head-left">
          <div class="mp-title-row">
            <div class="mp-title-info">
              <div class="mp-title">${mp_escape(title)}</div>
              <div class="mp-subtitle">نوع المادة: ${mp_escape(type)}</div>
            </div>

            <div class="mp-compact-total">
              <span>👁 ${mp_num(totals.views)} مشاهدات</span>
              <span>💬 ${mp_num(totals.comments)} تعليقات</span>
              <span>↗ ${mp_num(totals.shares)} مشاركات</span>
              <span>👍 ${mp_num(totals.likes)} إعجابات</span>
              <span>⚡ ${mp_num(totals.engagement_total)} تفاعل</span>
            </div>
          </div>
        </div>

        <div class="mp-actions">
          <button type="button" class="btn btn-xs btn-primary mp-open-row" data-cdn="${mp_escape(row.name)}">
            فتح الصف
          </button>

          <button type="button" class="mp-toggle-platforms" data-cdn="${mp_escape(row.name)}" title="عرض الإحصائيات">
            <span class="mp-toggle-icon">⌄</span>
          </button>
        </div>
      </div>

      <div class="mp-platforms" data-cdn="${mp_escape(row.name)}" style="display:none;">
        ${platforms_html}
      </div>
    </div>
  `;
}

function mp_build_platform_line(platform, link, summary) {
  const metrics = summary && summary.metrics ? summary.metrics : {};
  const fetched_at = summary && summary.fetched_at ? summary.fetched_at : "";

  return `
    <div class="mp-platform-line">
      <div class="mp-platform-name">
        <span>${platform.icon}</span>
        <span>${platform.label}</span>
      </div>

      <div class="mp-platform-stats">
        <span>👁 ${mp_num(metrics.views)}</span>
        <span>💬 ${mp_num(metrics.comments)}</span>
        <span>↗ ${mp_num(metrics.shares)}</span>
        <span>👍 ${mp_num(metrics.likes)}</span>
      </div>

      <div class="mp-platform-link">
        ${link ? `<a href="${mp_escape_attr(link)}" target="_blank">فتح الرابط</a>` : `<span class="mp-muted">لا يوجد رابط</span>`}
      </div>

      <div class="mp-fetched">
        ${fetched_at ? `آخر تحديث: ${mp_escape(fetched_at)}` : ""}
      </div>
    </div>
  `;
}

function mp_open_child_row(frm, cdn) {
  const grid = frm.fields_dict[MP_CFG.child_table_field].grid;
  const grid_row = grid.grid_rows_by_docname[cdn];

  if (grid_row) {
    grid_row.toggle_view(true);
  } else {
    frappe.msgprint("لم يتم العثور على الصف.");
  }
}

function mp_get_first_value(row, fields) {
  for (let i = 0; i < fields.length; i++) {
    const value = row[fields[i]];
    if (value !== undefined && value !== null && String(value).trim() !== "") {
      return value;
    }
  }
  return "";
}

function mp_parse_json(value) {
  if (!value) return null;

  try {
    return JSON.parse(value);
  } catch (e) {
    return null;
  }
}

function mp_num(value) {
  const n = Number(value || 0);
  return n.toLocaleString();
}

function mp_escape(value) {
  return frappe.utils.escape_html(String(value || ""));
}

function mp_escape_attr(value) {
  return mp_escape(value).replace(/"/g, "&quot;");
}

