function reset_plan_context(frm) {
  frm._plan_goals = [];
  frm._plan_messages = [];
  frm._plan_campaigns = [];
  frm._plan_events = [];
  frm._plan_audiences = [];

  frm.set_value("media_goal", "");
  frm.set_value("media_message", "");
  frm.set_value("media_campaign", "");
  frm.set_value("media_event", "");
  frm.set_value("target_audience", "");

  frm.clear_table("related_entities");
  frm.refresh_field("related_entities");
}

function setup_plan_filters(frm) {
  frm.set_query("media_goal", function () {
    return get_plan_filter(frm, frm._plan_goals);
  });

  frm.set_query("media_message", function () {
    return get_plan_filter(frm, frm._plan_messages);
  });

  frm.set_query("media_campaign", function () {
    return get_plan_filter(frm, frm._plan_campaigns);
  });

  frm.set_query("media_event", function () {
    return get_plan_filter(frm, frm._plan_events);
  });

  frm.set_query("target_audience", function () {
    return get_plan_filter(frm, frm._plan_audiences);
  });
}

function get_plan_filter(frm, values) {
  if (frm.doc.production_source !== "Planned") {
    return {};
  }

  if (!frm.doc.media_plan) {
    return {};
  }

  values = values || [];

  if (!values.length) {
    return {
      filters: [["name", "in", ["__no_result__"]]]
    };
  }

  return {
    filters: [["name", "in", values]]
  };
}

function load_plan_context(frm, clear_values) {
  reset_plan_arrays(frm);

  if (!frm.doc.media_plan) {
    reset_plan_context(frm);
    return;
  }

  frappe.db.get_doc("Media Plan", frm.doc.media_plan).then(function (plan) {
    (plan.goals || []).forEach(function (r) {
      if (r.media_goal) {
        frm._plan_goals.push(r.media_goal);
      }
    });

    (plan.messages || []).forEach(function (r) {
      if (r.media_message) {
        frm._plan_messages.push(r.media_message);
      }
    });

    (plan.campaigns || []).forEach(function (r) {
      if (r.media_campaign) {
        frm._plan_campaigns.push(r.media_campaign);
      }
    });

    (plan.events || []).forEach(function (r) {
      if (r.media_event) {
        frm._plan_events.push(r.media_event);
      }
    });

    (plan.target_audiences || []).forEach(function (r) {
      if (r.target_audience) {
        frm._plan_audiences.push(r.target_audience);
      }
    });

    if (clear_values) {
      frm.set_value("media_goal", "");
      frm.set_value("media_message", "");
      frm.set_value("media_campaign", "");
      frm.set_value("media_event", "");
      frm.set_value("target_audience", "");
    }

    frm.clear_table("related_entities");

    (plan.related_entities || []).forEach(function (r) {
      let row = frm.add_child("related_entities");
      row.entity = r.entity;
      row.entity_role = r.entity_role;
      row.notes = r.notes;
    });

    frm.refresh_field("related_entities");

    frappe.show_alert({
      message: __("Plan data loaded successfully"),
      indicator: "green"
    });
  });
}

function reset_plan_arrays(frm) {
  frm._plan_goals = [];
  frm._plan_messages = [];
  frm._plan_campaigns = [];
  frm._plan_events = [];
  frm._plan_audiences = [];
}

