function build_publication_html(rows) {
  if (!rows.length) {
    return `
      ${get_publication_style()}
      <div class="mpt-pub-empty">
        <div class="mpt-pub-empty-icon">📭</div>
        <div>${__("No publication data yet")}</div>
      </div>
    `;
  }

  const grouped = group_by_item(rows);

  let html = `
    ${get_publication_style()}
    <div class="mpt-pub-wrap">
      <div class="mpt-pub-header">
        <div>
          <div class="mpt-pub-title">${__("Platform Statistics")}</div>
          <div class="mpt-pub-subtitle">${__("Publication performance grouped by media item")}</div>
        </div>
        <div class="mpt-pub-badge">${rows.length} ${__("Publications")}</div>
