window.toggle_mpt_acc = function (id, el) {
  const body = document.getElementById(id);
  if (!body) return;

  const arrow = el.querySelector(".mpt-acc-arrow");
  const isOpen = body.style.display !== "none";

  body.style.display = isOpen ? "none" : "block";

  if (arrow) {
    arrow.textContent = isOpen ? "⌄" : "⌃";
  }
};

function group_by_item(rows) {
  const grouped = {};

  rows.forEach((row) => {
    const key = row.production_item_title || row.production_item_id || __("Untitled Item");
    if (!grouped[key]) {
      grouped[key] = [];
    }
    grouped[key].push(row);
  });

  return grouped;
}

function calc_totals(rows) {
  let views = 0;
  let engagement = 0;
  let positive = 0;
  let negative = 0;
  let mixed = 0;
  let neutral = 0;

  rows.forEach((row) => {
    views += Number(row.views || 0);
    engagement += Number(row.engagement_total || 0);

    const s = row.sentiment || "Neutral";
    if (s === "Positive") positive += 1;
    else if (s === "Negative") negative += 1;
    else if (s === "Mixed") mixed += 1;
    else neutral += 1;
  });

  let sentiment = "Neutral";
  if (positive >= negative && positive >= mixed && positive >= neutral) sentiment = "Positive";
  else if (negative >= positive && negative >= mixed && negative >= neutral) sentiment = "Negative";
  else if (mixed >= positive && mixed >= negative && mixed >= neutral) sentiment = "Mixed";

  return {
    views: views,
    engagement: engagement,
    sentiment: sentiment
  };
}

function platform_icon(platform) {
  const icons = {
    Facebook: "📘",
    YouTube: "▶️",
    Instagram: "📸",
    X: "𝕏",
    Website: "🌐",
    TV: "📺",
    Radio: "📻",
    Telegram: "✈️"
  };

  return icons[platform] || "🌐";
}

function sentiment_class(sentiment) {
  if (sentiment === "Positive") return "positive";
  if (sentiment === "Negative") return "negative";
  if (sentiment === "Mixed") return "mixed";
  return "neutral";
}

function format_num(value) {
  const n = Number(value || 0);
  return n.toLocaleString();
}

function escape_html(value) {
  return String(value || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function escape_attr(value) {
  return escape_html(value);
}

