// ===== متغير عام لحفظ حالة الـ accordions =====
let mpt_accordion_states = {};

function render_publication_statistics(frm) {
  if (!frm.fields_dict.publication_stats_html) {
    return;
  }

  if (frm.is_new()) {
    frm.fields_dict.publication_stats_html.$wrapper.html(`
      <div style="padding:16px;border:1px dashed #ddd;border-radius:12px;color:#6b7280;">
        ${__("Please save the document first to view publication statistics.")}
      </div>
    `);
    return;
  }

  frm.fields_dict.publication_stats_html.$wrapper.html(`
    <div style="padding:16px;border:1px solid #eee;border-radius:12px;color:#6b7280;">
      ${__("Loading publication statistics...")}
    </div>
  `);

  frappe.call({
    method: "frappe.client.get_list",
    args: {
      doctype: "Media Publication",
      filters: {
        media_production_test: frm.doc.name
      },
      fields: [
        "name",
        "publication_title",
        "production_item_id",
        "production_item_title",
        "platform",
        "post_url",
        "published_at",
        "views",
        "reach",
        "likes",
        "comments",
        "shares",
        "reactions_total",
        "engagement_total",
        "ai_summary",
        "sentiment",
        "sentiment_score",
        "fetched_at"
      ],
      limit_page_length: 500,
      order_by: "published_at desc"
    },
    callback(r) {
      const rows = r.message || [];
      frm.fields_dict.publication_stats_html.$wrapper.html(build_publication_html(rows));
      
      // ===== ربط أحداث أزرار التحديث بعد بناء الـ HTML =====
      bind_refresh_buttons();
      
      // ===== استعادة حالة الـ accordions =====
      restore_accordion_states();
    }
  });
}

// ===== حفظ حالة الـ accordions =====
function save_accordion_states() {
  mpt_accordion_states = {};
  const bodies = document.querySelectorAll(".mpt-accordion-body");
  bodies.forEach((body) => {
    const id = body.id;
    if (id) {
      mpt_accordion_states[id] = body.style.display !== "none";
    }
  });
}

// ===== استعادة حالة الـ accordions =====
function restore_accordion_states() {
  Object.keys(mpt_accordion_states).forEach((id) => {
    const body = document.getElementById(id);
    if (body) {
      const isOpen = mpt_accordion_states[id];
      body.style.display = isOpen ? "block" : "none";
      
      // تحديث السهم
      const card = body.closest(".mpt-item-card");
      if (card) {
        const arrow = card.querySelector(".mpt-acc-arrow");
        if (arrow) {
          arrow.textContent = isOpen ? "⌃" : "⌄";
        }
      }
    }
  });
}

// ===== ربط أحداث أزرار التحديث بشكل منفصل =====
function bind_refresh_buttons() {
  const buttons = document.querySelectorAll(".mpt-refresh-btn");
  buttons.forEach((btn) => {
    btn.addEventListener("click", function (e) {
      e.preventDefault();
      e.stopPropagation();
      e.stopImmediatePropagation();

      // ===== حفظ حالة الـ accordions قبل التحديث =====
      save_accordion_states();

      // إضافة حالة التحميل
      this.classList.add("is-loading");
      this.disabled = true;

      if (cur_frm && cur_frm.doctype === "Media Production Test") {
        render_publication_statistics(cur_frm);
      }
    });
  });
}

function build_publication_html(rows) {
  if (!rows.length) {
    return `
      ${get_publication_style()}
      <div class="mpt-pub-empty">
        <div class="mpt-pub-empty-icon">📭</div>
        <div>${__("No publication data yet")}</div>
      </div>
    `;
  }

  const grouped = group_by_item(rows);

  let html = `
    ${get_publication_style()}
    <div class="mpt-pub-wrap">
      <div class="mpt-pub-header">
        <div>
          <div class="mpt-pub-title">${__("Platform Statistics")}</div>
          <div class="mpt-pub-subtitle">${__("Publication performance grouped by media item")}</div>
        </div>
        <div class="mpt-pub-badge">${rows.length} ${__("Publications")}</div>
      </div>
  `;

  Object.keys(grouped).forEach((itemTitle, index) => {
    const itemRows = grouped[itemTitle];
    const totals = calc_totals(itemRows);
    const accId = "mpt-acc-" + index;

    html += `
      <div class="mpt-item-card">
        <div class="mpt-item-head mpt-accordion-head" onclick="toggle_mpt_acc('${accId}', this, event)">
          <div>
            <div class="mpt-item-title">${escape_html(itemTitle || __("Untitled Item"))}</div>
            <div class="mpt-item-meta">
              ${itemRows.length} ${__("Platforms")} ·
              ${format_num(totals.views)} ${__("Views")} ·
              ${format_num(totals.engagement)} ${__("Engagement")}
            </div>
          </div>

          <div class="mpt-head-actions">
            <button type="button" class="mpt-refresh-btn mpt-refresh-small" 
                    data-item-title="${escape_attr(itemTitle)}"
                    title="${__("Refresh")}">
              <span class="mpt-refresh-icon">🔄</span>
            </button>
            <div class="mpt-sentiment ${sentiment_class(totals.sentiment)}">
              ${escape_html(__(totals.sentiment || "Neutral"))}
            </div>
            <div class="mpt-acc-arrow"></div>
          </div>
        </div>

        <div id="${accId}" class="mpt-accordion-body" style="display:none;">
          <div class="mpt-platform-grid">
    `;

    itemRows.forEach((row) => {
      html += build_platform_card(row);
    });

    html += `
          </div>
        </div>
      </div>
    `;
  });

  html += `</div>`;
  return html;
}

function build_platform_card(row) {
  const platform = row.platform || "-";
  const sentiment = row.sentiment || "Neutral";

  return `
    <div class="mpt-platform-card">
      <div class="mpt-platform-head">
        <div class="mpt-platform-name">${platform_icon(platform)} ${escape_html(__(platform))}</div>
        <div class="mpt-platform-sentiment ${sentiment_class(sentiment)}">
          ${escape_html(__(sentiment))}
        </div>
      </div>

      <div class="mpt-metrics">
        <div class="mpt-metric">
          <span>${__("Views")}</span>
          <strong>${format_num(row.views)}</strong>
        </div>
        <div class="mpt-metric">
          <span>${__("Reach")}</span>
          <strong>${format_num(row.reach)}</strong>
        </div>
        <div class="mpt-metric">
          <span>${__("Likes")}</span>
          <strong>${format_num(row.likes)}</strong>
        </div>
        <div class="mpt-metric">
          <span>${__("Comments")}</span>
          <strong>${format_num(row.comments)}</strong>
        </div>
        <div class="mpt-metric">
          <span>${__("Shares")}</span>
          <strong>${format_num(row.shares)}</strong>
        </div>
        <div class="mpt-metric highlight">
          <span>${__("Engagement")}</span>
          <strong>${format_num(row.engagement_total)}</strong>
        </div>
      </div>

      ${
        row.ai_summary
          ? `<div class="mpt-ai">
