frappe.ui.form.on('Issue', {
    refresh: function(frm) {
        // جلب حالة الوورك فلو الحالية
        const current_state = frm.doc.workflow_state || "Draft";
        
        // مصفوفة الحالات الأساسية المشتركة
        let states = ["Draft", "Pending", "Working"];
        
        // إذا كان المستند مغلقاً، نقوم بالاستعلام الصحيح من قاعدة البيانات للتأكد من المسار
        if (current_state === "Closed" && frm.doc.name) {
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Workflow Action",
                    filters: {
                        reference_name: frm.doc.name, // التصحيح هنا: استخدام reference_name بدلاً من docname
                        status: "Completed"
                    },
                    fields: ["workflow_state"],
                    order_by: "creation desc",
                    limit: 20
                },
                callback: function(r) {
                    let is_replied_path = false;
                    if (r.message && r.message.length > 0) {
                        // فحص سجل الحركة: هل مر الطلب بحالة Replied؟
                        is_replied_path = r.message.some(log => log.workflow_state === "Replied");
                    }
                    // رندر الشريط بناءً على النتيجة الحقيقية
                    render_custom_timeline(frm, states, current_state, is_replied_path);
                }
            });
        } else {
            // إذا كان الطلب في الحالات العادية، نحدد المسار فوراً بناءً على الحالة الحالية
            let is_replied_path = (current_state === "Replied");
            render_custom_timeline(frm, states, current_state, is_replied_path);
        }
    }
});

// دالة بناء ورسم شريط الخطوات بشكل ثابت ومحمي
function render_custom_timeline(frm, states, current_state, is_replied_path) {
    // إضافة الخطوة الرابعة ديناميكياً بناءً على المسار المتخذ
    if (is_replied_path) {
        states.push("Replied");
    } else {
        states.push("Resolved");
    }
    
    // إضافة الحالة النهائية دائماً
    states.push("Closed");
    
    // بناء شريط الخطوات بـ HTML و CSS
    let html = `
        <div class="workflow-steps-container" style="display: flex; justify-content: space-between; align-items: center; margin: 15px 0; padding: 10px; background: #f8f9fa; border-radius: 8px; border: 1px solid #d1d8dd;">
    `;
    
    states.forEach((state, index) => {
        // الحفاظ على تلوين الشريط بالكامل بالأخضر عند الإغلاق (Closed)
        const is_completed_or_current = current_state === "Closed" || states.indexOf(current_state) >= index;
        
        const color = is_completed_or_current ? "#28a745" : "#6c757d"; 
        const font_weight = current_state === state ? "bold" : "normal";
        const border_style = current_state === state ? "3px solid #28a745" : "1px solid " + color;
        
        html += `
            <div class="step-item" style="flex: 1; text-align: center; position: relative;">
                <div class="step-circle" style="width: 30px; height: 30px; border-radius: 50%; background: ${is_completed_or_current ? '#28a745' : '#fff'}; border: ${border_style}; color: ${is_completed_or_current ? '#fff' : '#6c757d'}; display: flex; align-items: center; justify-content: center; margin: 0 auto 5px auto; font-weight: bold; font-size: 12px; z-index: 2; position: relative;">
                    ${index + 1}
                </div>
                <div class="step-label" style="color: ${color}; font-weight: ${font_weight}; font-size: 12px;">
                    ${__(state)}
                </div>
        `;
        
        // رسم وتلوين الخطوط الواصلة بين الخطوات
        if (index < states.length - 1) {
            const line_color = (current_state === "Closed" || states.indexOf(current_state) > index) ? "#28a745" : "#d1d8dd";
            html += `<div class="step-line" style="position: absolute; top: 15px; left: 50%; width: 100%; height: 2px; background: ${line_color}; z-index: 1;"></div>`;
        }
        
        html += `</div>`;
    });
    
    html += `</div>`;
    
    // حقن الشريط وتحديث الـ Headline في الأعلى بشكل ثابت ومستمر
    frm.dashboard.clear_headline();
    frm.dashboard.set_headline(html);
}

frappe.listview_settings['Issue'] = {
    onload: function(listview) {
        // منع تكرار تفعيل المؤقت عند التنقل في النظام
        if (!window.issue_polling_sound_applied) {
            console.log("تم تشغيل نظام الفحص الدوري الذكي لصوت التذاكر.");

            // متغير لحفظ معرّف آخر إشعار تم رصده لمنع التكرار
            window.last_tracked_notification = "";

            // 1. جلب آخر إشعار متواجد حالياً في النظام عند تحميل الصفحة (لاعتباره نقطة انطلاق وتجنب تشغيل الأصوات القديمة)
            frappe.db.get_list('Notification Log', {
                fields: ['name'],
                order_by: 'creation desc',
                limit: 1
            }).then(records => {
                if (records && records.length > 0) {
                    window.last_tracked_notification = records[0].name;
                }

                // 2. بدء الفحص الآلي كل 3 ثوانٍ في الخلفية
                setInterval(function() {
                    frappe.db.get_list('Notification Log', {
                        fields: ['name', 'subject'],
                        order_by: 'creation desc',
                        limit: 1
                    }).then(new_records => {
                        if (new_records && new_records.length > 0) {
                            let latest = new_records[0];

                            // التحقق مما إذا كان هذا الإشعار جديداً بالكامل ولم نقم بمعالجته بعد
                            if (latest.name !== window.last_tracked_notification) {
                                // تحديث المرجع فوراً لمنع التكرار في الدورة القادمة
                                window.last_tracked_notification = latest.name;

                                // فحص ما إذا كان موضوع الإشعار يحتوي على النص المطلوب
                                if (latest.subject && latest.subject.includes("تذكرة دعم فني جديدة قيد الانتظار")) {
                                    
                                    // إطلاق الصوت المعتمد محلياً
                                    const audio = new Audio('/files/notification.mp3');
                                    audio.play().then(() => {
                                        console.log("تم إصدار صوت الإشعار بنجاح عبر الفحص الدوري.");
                                    }).catch(e => {
                                        console.warn("المتصفح حظر التشغيل التلقائي، يرجى الضغط داخل الصفحة لتفعيله:", e);
                                    });
                                    
                                }
                            }
                        }
                    });
                }, 3000); // 3000 ميلي ثانية = 3 ثوانٍ
            });

            window.issue_polling_sound_applied = true;
        }
    }
};

frappe.ui.form.on('Influencer Event', {
    // Trigger this function when the geolocation field changes
    location_map: function(frm) {
        if (frm.doc.location_map) {
            try {
                // 1. Parse the GeoJSON string
                var geo_data = JSON.parse(frm.doc.location_map);
                
                // 2. Check if there are features
                if (geo_data.features && geo_data.features.length > 0) {
                    
                    // 3. Get the coordinates array [Longitude, Latitude]
                    var coords = geo_data.features[0].geometry.coordinates;
                    
                    // 4. Set the values to your separate fields
                    // Note: GeoJSON stores [Longitude, Latitude]
                    frm.set_value('longitude', coords[0]);
                    frm.set_value('latitude', coords[1]);
                    
                    // 5. Refresh the fields to show the new numbers
                    frm.refresh_field('longitude');
                    frm.refresh_field('latitude');
                }
            } catch (e) {
                // If JSON parsing fails, do nothing
                console.log("Error parsing location", e);
            }
        }
    }
});

frappe.ui.form.on('Influencer Event', {
    validate: function(frm) {
        // 1. جلب البيانات من الوثيقة الأب (الحدث)
        // تنبيه: تأكد من تغيير أسماء الحقول (title, event_date) إذا كانت مختلفة في نظامك
        let event_title = frm.doc.title || frm.doc.event_name || "Event";
        let event_date = frm.doc.event_date || frm.doc.start_date || frappe.datetime.nowdate();
        
        // تنظيف العنوان: إزالة المسافات والرموز الخاصة لجعله صالحاً ومقروءاً لـ QR
        let clean_title = event_title.replace(/[\s\W_]+/g, '-').replace(/^-+|-+$/g, '');
        
        // تنسيق التاريخ ليكون بصيغة YYYYMMDD
        let date_obj = frappe.datetime.str_to_obj(event_date);
        let formatted_date = date_obj ? 
            frappe.datetime.str_to_obj(event_date).toISOString().slice(0,10).replace(/-/g, '') : 
            frappe.datetime.nowdate().replace(/-/g, '');

        // 2. المرور على صفوف جدول الأطفال (content_creators)
        $.each(frm.doc.content_creators || [], function(i, row) {
            // إذا كان حقل qr_code فارغاً، قم بتوليد القيمة
            if (!row.qr_code) {
                
                // الخيار الأول: استخدام رقم السطر (idx) لضمان التفرد
                let unique_string = `${clean_title}-${formatted_date}-${row.idx}`;
                
                // الخيار الثاني (مُوصى به): إذا كان لديك حقل مميز في صف الطفل (مثل اسم المؤثر أو المستخدم)
                // يمكنك إلغاء التعليق عن الأسطر التالية واستخدامها بدلاً من idx
                /*
                let influencer_id = row.influencer_name || row.user || "";
                if (influencer_id) {
                    let clean_influencer = influencer_id.replace(/[\s\W_]+/g, '-').replace(/^-+|-+$/g, '');
                    unique_string = `${clean_title}-${formatted_date}-${clean_influencer}`;
                }
                */

                // حفظ القيمة في الحقل
                row.qr_code = unique_string;
            }
        });
    }
});

