frappe.ui.form.on('Issue', {
    // 1. حدث تحميل الصفحة (Onload) - لتهيئة الحقول
    onload: function(frm) {
        // قفل حقول الموظف لتكون للقراءة فقط دائماً
        frm.set_df_property('custom_employee_name_copy', 'read_only', 1);
        frm.set_df_property('custom_full_name', 'read_only', 1);
        frm.set_df_property('custom_designation', 'read_only', 1);
        frm.set_df_property('custom_department', 'read_only', 1);
    },

    // 2. حدث التحديث (Refresh) - لتنفيذ المنطق الرئيسي
    refresh: function(frm) {
        // تعريف المتغيرات الأساسية
        const current_state = frm.doc.workflow_state || "Draft";
        const is_owner = (frappe.session.user === frm.doc.owner);
        const is_support = frappe.user.has_role('Support Team');
        const is_employee = frappe.user.has_role('Employee');

        // --- أ. جلب بيانات الموظف تلقائياً للمستندات الجديدة ---
        if (frm.is_new()) {
            frappe.db.get_value('Employee', { 'user_id': frappe.session.user }, 'name', (r) => {
                if (r && r.name) {
                    frm.set_value('custom_employee_name_copy', r.name);
                }
            });
        }

        // --- ب. تجاوز القيود لمسؤول الدعم ---
        if (is_support) {
            frm.ignore_user_permissions = true;
        }

        // --- ج. التحكم في ظهور الأقسام والـ Dashboard بناءً على الرول والحالة ---
        if (is_employee && !is_support) {
            // إخفاء الـ Connections عن الموظف
            if (frm.dashboard) frm.dashboard.hide();
            
            // إظهار قسم العنوان والوصف دائماً للموظف
            frm.toggle_display('subject_section', true);
            
            // **التحكم الذكي في قسم التقييم للموظف:**
            if (current_state === 'Replied' || current_state === 'Resolved') {
                // إظهار قسم التقييم فقط بعد حل التذكرة
                frm.toggle_display('custom_section_break_zlfsg', true);
            } else {
                // إخفاء قسم التقييم قبل التقديم وأثناء العمل على المشكلة
                frm.toggle_display('custom_section_break_zlfsg', false);
            }
            
            // إخفاء الأقسام الخاصة بالدعم الفني عن الموظف
            frm.toggle_display('sb_details', false); 
            frm.toggle_display('service_level_section', false);
            frm.toggle_display('section_break_19', false);
            frm.toggle_display('additional_info', false);
            frm.toggle_display('response', false);
            
        } else if (is_support) {
            // إظهار كل شيء لمسؤول الدعم في كافة الحالات
            if (frm.dashboard) frm.dashboard.show();
            frm.toggle_display('subject_section', true);
            frm.toggle_display('custom_section_break_zlfsg', true);
            frm.toggle_display('sb_details', true); 
            frm.toggle_display('service_level_section', true);
            frm.toggle_display('section_break_19', true);
            frm.toggle_display('additional_info', true);
            frm.toggle_display('response', true);
        }

        // --- د. منطق القراءة والكتابة (قفل وفتح الحقول) ---
        if (is_owner && !is_support) {
            // إذا كانت التذكرة في مرحلة الحل (وقت التقييم الحالي)
            if (current_state === 'Replied' || current_state === 'Resolved') {
                frm.enable_save(); 
                
                // قفل الحقول الأساسية لعدم التلاعب بها
                frm.set_df_property('subject', 'read_only', 1);
                frm.set_df_property('description', 'read_only', 1);
                
                // جعل حقل التقييم داخل القسم قابلاً للكتابة والتعديل
                frm.set_df_property('custom_customer_satisfaction', 'read_only', 0);
            } 
            // إذا كانت التذكرة مغلقة تماماً
            else if (current_state === 'Closed') {
                frm.disable_save();
                frm.set_read_only(); // إغلاق المستند بالكامل للقراءة فقط
            }
        }

        // إبقاء زر الحفظ متاحاً دائماً للدعم الفني
        if (is_support) {
            frm.enable_save();
        }
    },

    // 3. حدث "قبل الإغلاق" - الإجبار على التقييم
    before_workflow_action: function(frm) {
        let action = frm.selected_workflow_action;
        
        if (action === 'Close' || action === 'Closed') {
            const is_owner = (frappe.session.user === frm.doc.owner);
            const is_support = frappe.user.has_role('Support Team');
            
            // إذا كان الموظف يحاول الإغلاق وحقل التقييم فارغ
            if (is_owner && !is_support) {
                if (!frm.doc.custom_customer_satisfaction) {
                    frappe.throw(__('عذراً، يرجى تقييم مستوى الخدمة قبل إغلاق التذكرة.'));
                    frappe.validated = false; 
                }
            }
        }
    }
});

