            frm.toggle_display('sb_details', true);
            frm.toggle_display('service_level_section', true);
            frm.toggle_display('section_break_19', true);
            frm.toggle_display('additional_info', true);
            frm.toggle_display('response', true);
            frm.toggle_display('iso_nonconformity_section', true);
        }

        // ج. منطق القراءة والكتابة للتقييم وقفل الحقول عند التقييم
        if (is_owner && !is_support) {
