function render_workflow_progress(frm) {
    if (!frm.get_field('workflow_progress_html')) return;

    const current_status = frm.doc.request_status;
    
    // فحص لغة النظام الحالية (هل هي عربية؟)
    const is_arabic = (frappe.boot.lang === 'ar');
    const direction = is_arabic ? 'rtl' : 'ltr';
    const line_side = is_arabic ? 'right' : 'left'; // لضبط اتجاه الخط الواصل بين الدوائر

    // تحديد مسميات الخطوات بناءً على اللغة المتوفرة في المتصفح
    const steps = is_arabic ? [
        { id: "Pending", label: "قيد الانتظار" },
        { id: "Awaiting Approval", label: "بانتظار الموافقة" },
        { id: "Awaiting Assignment", label: "بانتظار التعيين" },
        { id: "Approved and Scheduled", label: "مقبول ومجدول" },
        { id: "Completed", label: "مكتمل" }
    ] : [
        { id: "Pending", label: "Pending" },
        { id: "Awaiting Approval", label: "Awaiting Approval" },
        { id: "Awaiting Assignment", label: "Awaiting Assignment" },
        { id: "Approved and Scheduled", label: "Approved & Scheduled" },
        { id: "Completed", label: "Completed" }
    ];

    // تصميم الـ CSS الديناميكي الذي يتغير حسب اتجاه اللغة
    let html = `
    <style>
        .progress-stepper {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin: 20px 10px;
            direction: ${direction};
        }
        .step-item {
            text-align: center;
            flex: 1;
            position: relative;
        }
        /* الخط الواصل يدعم الـ RTL والـ LTR ديناميكياً */
        .step-item:not(:last-child)::after {
            content: '';
            position: absolute;
            top: 15px;
            ${line_side}: 50%;
            width: 100%;
            height: 3px;
            background-color: #e0e0e0;
            z-index: 1;
        }
        .step-item.completed:not(:last-child)::after {
            background-color: #28a745;
        }
        .step-circle {
            width: 32px;
            height: 32px;
            border-radius: 50%;
            background-color: #e0e0e0;
            color: #fff;
            display: flex;
            align-items: center;
            justify-content: center;
            margin: 0 auto 10px auto;
            position: relative;
            z-index: 2;
            font-weight: bold;
            font-size: 14px;
        }
        .step-item.active .step-circle {
            background-color: #28a745;
            box-shadow: 0 0 0 4px rgba(40, 167, 69, 0.25);
        }
        .step-item.completed .step-circle {
            background-color: #28a745;
        }
        .step-label {
            font-size: 12px;
            color: #8c8c8c;
            font-weight: 500;
        }
        .step-item.active .step-label, 
        .step-item.completed .step-label {
            color: #28a745;
            font-weight: bold;
        }
    </style>
    `;

    if (current_status === "Rejected") {
        const rejected_msg = is_arabic ? "❌ تم رفض هذا الطلب (Rejected)" : "❌ This request has been Rejected";
        html += `
        <div class="alert alert-danger text-center" style="margin: 20px 0; font-weight: bold; border-radius: 8px;">
            ${rejected_msg}
        </div>
        `;
    } else {
        html += '<div class="progress-stepper">';
        let current_index = steps.findIndex(step => step.id === current_status);
        
        if (current_index === -1) {
            current_index = 0; 
        }
        
        steps.forEach((step, index) => {
            let step_class = "";
            if (index < current_index) {
                step_class = "completed";
            } else if (index === current_index) {
                step_class = "active";
            }

            let display_number = (index < current_index) ? "✓" : (index + 1);

            html += `
            <div class="step-item ${step_class}">
                <div class="step-circle">${display_number}</div>
                <div class="step-label">${step.label}</div>
            </div>
            `;
        });
        html += '</div>';
    }

    frm.get_field('workflow_progress_html').$wrapper.html(html);
}

