function render_furniture_moving_progress(frm) {
    // التأكد من وجود الحقل المخصص في النموذج لتجنب أي توقف
    if (!frm.get_field('furniture_moving_progress_html')) return;

    // اسم الحقل البرمجي للحالة هو status من واقع الصورة
    const current_status = frm.doc.status;
    
    // فحص لغة واجهة النظام الحالية لقلب الاتجاه والمسميات
    const is_arabic = (frappe.boot.lang === 'ar');
    const direction = is_arabic ? 'rtl' : 'ltr';
    const line_side = is_arabic ? 'right' : 'left';

    // بناءً على مصمم سير العمل الجديد: الحالات الأساسية بالترتيب
    const steps = is_arabic ? [
        { id: "Draft", label: "مسودة" },
        { id: "Open", label: "مفتوح" },
        { id: "Working", label: "قيد التنفيذ" },
        { id: "Completed", label: "مكتمل" }
    ] : [
        { id: "Draft", label: "Draft" },
        { id: "Open", label: "Open" },
        { id: "Working", label: "Working" },
        { id: "Completed", label: "Completed" }
    ];

    // تصميم الـ CSS المرن ثنائي اللغة والاتجاهات
    let html = `
    <style>
        .progress-stepper {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin: 20px 10px;
            direction: ${direction};
        }
        .step-item {
            text-align: center;
            flex: 1;
            position: relative;
        }
        /* الخط الواصل بين الدوائر يتغير اتجاهه ديناميكياً */
        .step-item:not(:last-child)::after {
            content: '';
            position: absolute;
            top: 15px;
            ${line_side}: 50%;
            width: 100%;
            height: 3px;
            background-color: #e0e0e0;
            z-index: 1;
        }
        .step-item.completed:not(:last-child)::after {
            background-color: #28a745;
        }
        .step-circle {
            width: 32px;
            height: 32px;
            border-radius: 50%;
            background-color: #e0e0e0;
            color: #fff;
            display: flex;
            align-items: center;
            justify-content: center;
            margin: 0 auto 10px auto;
            position: relative;
            z-index: 2;
            font-weight: bold;
            font-size: 14px;
        }
        .step-item.active .step-circle {
            background-color: #28a745;
            box-shadow: 0 0 0 4px rgba(40, 167, 69, 0.25);
        }
        .step-item.completed .step-circle {
            background-color: #28a745;
        }
        .step-label {
            font-size: 12px;
            color: #8c8c8c;
            font-weight: 500;
        }
        .step-item.active .step-label, 
        .step-item.completed .step-label {
            color: #28a745;
            font-weight: bold;
        }
    </style>
    `;

    // التعامل مع حالة الرفض Rejected لمنع كسر انسيابية الشريط
    if (current_status === "Rejected") {
        const cancel_msg = is_arabic ? "❌ تم رفض هذا الطلب (Rejected)" : "❌ This request has been Rejected";
        html += `
        <div class="alert alert-danger text-center" style="margin: 20px 0; font-weight: bold; border-radius: 8px;">
            ${cancel_msg}
        </div>
        `;
    } else {
        html += '<div class="progress-stepper">';
        let current_index = steps.findIndex(step => step.id === current_status);
        
        if (current_index === -1) {
            current_index = 0; // الحالة الافتراضية عند البدء هي مسودة Draft
        }
        
        steps.forEach((step, index) => {
            let step_class = "";
            if (index < current_index) {
                step_class = "completed";
            } else if (index === current_index) {
                step_class = "active";
            }

            let display_number = (index < current_index) ? "✓" : (index + 1);

            html += `
            <div class="step-item ${step_class}">
                <div class="step-circle">${display_number}</div>
                <div class="step-label">${step.label}</div>
            </div>
            `;
        });
        html += '</div>';
    }

    // حقن محتوى الـ HTML المشيّد داخل الحقل المخصص
    frm.get_field('furniture_moving_progress_html').$wrapper.html(html);
}

