function calculate_custom_scores(frm) {
    let total = 0;

    (frm.doc.appraisal_kra || []).forEach(function(row) {

        row.custom_weighted_score =
            (flt(row.per_weightage) * flt(row.custom_evaluation)) / 100;

        total += flt(row.custom_weighted_score);
    });

    frm.refresh_field("appraisal_kra");
    frm.set_value("custom_total_score", total);
}

