async function export_interviews_excel(listview){


    if(typeof XLSX === "undefined"){

        frappe.msgprint(
            "جاري تحميل مكتبة Excel، أعد المحاولة"
        );

        return;

    }



    frappe.show_alert({
        message:"⏳ جاري تجهيز التقرير",
        indicator:"blue"
    });



    try{


        // قراءة الفلاتر الحالية من List View

        let filters = {};


        if(listview.filter_area){


            let applied_filters =
                listview.filter_area.get();



            applied_filters.forEach(f=>{


                let field = f[1];

                let operator = f[2];

                let value = f[3];



                if(operator === "="){

                    filters[field] = value;

                }

                else {

                    filters[field] = [
                        operator,
                        value
                    ];

                }


            });


        }




        let interviews = await frappe.db.get_list(
            "Interview",
            {

                filters: filters,

                fields:[

                    "name",
                    "job_applicant",
                    "status",
                    "interview_round"

                ],

                order_by:"creation desc",

                limit_page_length:10000

            }
        );




        if(interviews.length===0){

            frappe.msgprint(
                "لا توجد مقابلات للتصدير"
            );

            return;

        }




        let cleared=[];

        let rejected=[];




        for(let item of interviews){


            let doc =
                await frappe.db.get_doc(
                    "Interview",
                    item.name
                );



            let weights={};



            (doc.committee_members || [])
            .forEach(member=>{


                weights[member.member_type] =
                    Number(member.weight || 0);


            });





            let member_scores={};



            (doc.member_evaluations || [])
            .forEach(ev=>{


                if(!ev.max_score){

                    return;

                }



                if(!member_scores[ev.committee_member]){


                    member_scores[ev.committee_member]={

                        score:0,
                        max:0

                    };


                }



                member_scores[ev.committee_member].score +=
                    Number(ev.score || 0);



                member_scores[ev.committee_member].max +=
                    Number(ev.max_score || 0);



            });





            let categories={};



            for(let member in member_scores){


                let data =
                    member_scores[member];



                if(data.max===0){

                    continue;

                }



                let percent =
                    (data.score / data.max) * 100;



                let committee_member =
                    (doc.committee_members || [])
                    .find(
                        c=>c.member===member
                    );



                if(!committee_member){

                    continue;

                }



                let type =
                    committee_member.member_type;



                if(!categories[type]){

                    categories[type]=[];

                }



                categories[type].push(percent);


            }




            let final_categories={};



            for(let type in categories){


                let total=0;



                categories[type].forEach(v=>{

                    total += v;

                });



                final_categories[type] =
                    total / categories[type].length;


            }





            let final_score=0;



            for(let type in final_categories){


                final_score +=

                    final_categories[type]
                    *
                    (weights[type] || 0)
                    /
                    100;


            }





            let applicant="";



            if(item.job_applicant){


                let result =
                    await frappe.db.get_value(
                        "Job Applicant",
                        item.job_applicant,
                        "applicant_name"
                    );


                applicant =
                    result.message.applicant_name || "";


            }





            let result_row={


                applicant: applicant,

                HR:
                    Number(
                        final_categories["HR"] || 0
                    ).toFixed(2),



                Administrative:
                    Number(
                        final_categories["إداري"] || 0
                    ).toFixed(2),



                Technical:
                    Number(
                        final_categories["فني"] || 0
                    ).toFixed(2),



                Final:
                    Number(final_score)
                    .toFixed(2),



                Status:item.status


            };





            if(item.status==="Cleared"){

                cleared.push(result_row);

            }



            else if(item.status==="Rejected"){

                rejected.push(result_row);

            }



        }





        cleared.sort(
            (a,b)=>
            Number(b.Final)-Number(a.Final)
        );





        let excel_rows=[];



        excel_rows.push([
            "المقبولون"
        ]);



        excel_rows.push([

            "م",
            "اسم المتقدم",
            "HR %",
            "إداري %",
            "فني %",
            "المجموع",
            "الحالة"

        ]);



        let index=1;



        cleared.forEach(r=>{


            excel_rows.push([

                index++,
                r.applicant,
                r.HR,
                r.Administrative,
                r.Technical,
                r.Final,
                r.Status

            ]);


        });





        excel_rows.push([]);

        excel_rows.push([
            "المرفوضون"
        ]);



        excel_rows.push([

            "م",
            "اسم المتقدم",
            "HR %",
            "إداري %",
            "فني %",
            "المجموع",
            "الحالة"

        ]);



        index=1;



        rejected.forEach(r=>{


            excel_rows.push([

                index++,
                r.applicant,
                r.HR,
                r.Administrative,
                r.Technical,
                r.Final,
                r.Status

            ]);


        });





        let wb =
            XLSX.utils.book_new();



        let ws =
            XLSX.utils.aoa_to_sheet(
                excel_rows
            );




        ws['!cols']=[

            {wch:8},
            {wch:25},
            {wch:12},
            {wch:12},
            {wch:12},
            {wch:12},
            {wch:15}

        ];





        XLSX.utils.book_append_sheet(

            wb,

            ws,

            "نتائج المقابلات"

        );





        XLSX.writeFile(

            wb,

            "Interview_Report.xlsx"

        );





        frappe.show_alert({

            message:"✅ تم تصدير ملف Excel",

            indicator:"green"

        },3);



    }


    catch(e){


        console.error(e);


        frappe.msgprint(
            "خطأ: " + e.message
        );


    }


}

frappe.ui.form.on("Leave Application", {
  before_save: async function (frm) {
    // Apply the deadline to the employee's initial request only. Existing
    // requests must remain actionable for managers at any later date.
    if (!frm.is_new() || !frm.doc.leave_type || !frm.doc.from_date) return;

    const response = await frappe.db.get_value(
      "Leave Type",
      frm.doc.leave_type,
      ["custom_leave_submission_offset_days", "custom_only_allow_for_role"]
    );
    const rule = response.message || {};
    const bypassRole = rule.custom_only_allow_for_role;
    const canBypassDeadline = frappe.session.user === "Administrator"
      || (bypassRole && frappe.user_roles.includes(bypassRole));

    const offset = cint(rule.custom_leave_submission_offset_days || 0);
    const deadline = frappe.datetime.add_days(frm.doc.from_date, offset);
    const today = frappe.datetime.get_today();

    if (!canBypassDeadline && frappe.datetime.get_diff(today, deadline) > 0) {
      frappe.throw(__(
        "This leave application can no longer be submitted. The latest allowed submission date is {0}.",
        [frappe.datetime.str_to_user(deadline)]
      ));
    }
  }
});

