  var approvalDecisionFields = ["approval_decision","approval_notes"];
  var planningFields = ["change_owner","implementing_team","planned_start","planned_end","implementation_plan","testing_plan","rollback_plan","communication_plan"];
  var implementationFields = ["implementation_result","rollback_required","rollback_result"];
  var verificationFields = ["verification_result","verification_notes"];
  var closureFields = ["closure_notes"];

  function hasRole(role) {
    return frappe.session.user === "Administrator" || (frappe.user_roles || []).indexOf(role) !== -1;
  }
  function setReadOnly(frm, fields, readOnly) {
    fields.forEach(function (fieldname) {
      if (frm.fields_dict[fieldname]) frm.set_df_property(fieldname, "read_only", readOnly ? 1 : 0);
    });
  }
  function applyStage(frm) {
    var state = frm.doc.workflow_state || frm.doc.status || "Draft";
    var visible = ["request_details_section"];

    if (state === "Under Assessment") {
      visible = ["request_details_section","classification_section","related_records_section","affected_components_section","impact_assessment_section","ownership_section","approval_section"];
    } else if (state === "Pending Approval") {
      visible = ["request_details_section","classification_section","affected_components_section","impact_assessment_section","approval_section"];
    } else if (state === "Approved" || state === "Scheduled") {
      visible = ["request_details_section","impact_assessment_section","approval_section","ownership_section"];
    } else if (state === "In progress") {
      visible = ["request_details_section","affected_components_section","ownership_section","implementation_section"];
    } else if (state === "Pending Verification" || state === "Verified" || state === "Closed") {
      visible = ["request_details_section","implementation_section","verification_section"];
    } else if (state === "Rejected") {
      visible = ["request_details_section","impact_assessment_section","approval_section"];
    } else if (state === "Failed" || state === "Rolled Back") {
      visible = ["request_details_section","implementation_section","verification_section"];
    } else if (state === "Cancelled") {
      visible = ["request_details_section","verification_section"];
    }

    sections.forEach(function (section) {
      if (frm.fields_dict[section]) frm.toggle_display(section, visible.indexOf(section) !== -1);
    });

    var systemManager = hasRole("System Manager");
    var requester = frm.doc.requested_by === frappe.session.user;
    setReadOnly(frm, requestFields, !(systemManager || (state === "Draft" && (requester || hasRole("Change Manager")))));
    setReadOnly(frm, assessmentFields, !(systemManager || (state === "Under Assessment" && hasRole("Change Manager"))));
    setReadOnly(frm, approvalAssignmentFields, !(systemManager || (state === "Under Assessment" && hasRole("Change Manager"))));
    setReadOnly(frm, approvalDecisionFields, !(systemManager || (state === "Pending Approval" && hasRole("Technical Approver"))));
    var planningEditable = systemManager || (state === "Under Assessment" && hasRole("Change Manager")) || ((state === "Approved" || state === "Scheduled") && (hasRole("Change Manager") || hasRole("Change Owner")));
    setReadOnly(frm, planningFields, !planningEditable);
    setReadOnly(frm, implementationFields, !(systemManager || (state === "In progress" && hasRole("Change Owner"))));
    setReadOnly(frm, verificationFields, !(systemManager || (state === "Pending Verification" && hasRole("Technical Approver"))));
    setReadOnly(frm, closureFields, !(systemManager || (state === "Verified" && requester)));
    if (frm.fields_dict.rollback_result) {
      var rollbackEditable = systemManager || (state === "In progress" && hasRole("Change Owner")) || (state === "Pending Verification" && hasRole("Technical Approver"));
      frm.set_df_property("rollback_result", "read_only", rollbackEditable ? 0 : 1);
    }

    ["change_title","priority","change_description","requested_date","requested_by"].forEach(function (fieldname) {
      frm.toggle_reqd(fieldname, state === "Draft");
    });
    ["change_type","change_category","change_source","business_impact","technical_impact","security_impact","service_impact","risk_assessment","change_owner","approver"].forEach(function (fieldname) {
      frm.toggle_reqd(fieldname, state === "Pending Approval");
    });
    frm.toggle_reqd("emergency_justification", state === "Pending Approval" && frm.doc.change_category === "Emergency Change");
    ["change_owner","planned_start","planned_end","implementation_plan","testing_plan","rollback_plan","communication_plan"].forEach(function (fieldname) {
      frm.toggle_reqd(fieldname, state === "Scheduled");
    });
    frm.toggle_reqd("implementation_result", state === "Pending Verification" || state === "Failed");
    frm.toggle_reqd("rollback_result", state === "Rolled Back");
    frm.toggle_reqd("verification_result", state === "Verified");
  }

  frappe.ui.form.on("Digital Change Request", {
    refresh: applyStage,
    workflow_state: applyStage,
    status: applyStage,
    change_category: applyStage,
    requested_by: applyStage
  });
})();

