// INTERNAL_AUDIT_CHECKLIST_AUTOMATION_V1
(function () {
  function apply_result(row) {
    const scores = {
      "Conformity": 100,
      "Opportunity for Improvement": 75,
      "Minor Nonconformity": 50,
      "Major Nonconformity": 0
    };
    const findingResults = [
      "Opportunity for Improvement",
      "Minor Nonconformity",
      "Major Nonconformity"
    ];
    row.score = Object.prototype.hasOwnProperty.call(scores, row.audit_result)
      ? scores[row.audit_result] : null;
    row.finding_required = findingResults.includes(row.audit_result) ? 1 : 0;
  }

  function calculate_summary(frm) {
    const rows = frm.doc.audit_checklist || [];
    const counts = {
      conformity: 0, ofi: 0, minor: 0, major: 0, na: 0,
      audited: 0, scoreSum: 0, scored: 0
    };
    rows.forEach(function (row, index) {
      row.sequence = index + 1;
      apply_result(row);
      if (row.audit_result === "Conformity") counts.conformity += 1;
      if (row.audit_result === "Opportunity for Improvement") counts.ofi += 1;
      if (row.audit_result === "Minor Nonconformity") counts.minor += 1;
      if (row.audit_result === "Major Nonconformity") counts.major += 1;
      if (row.audit_result === "Not Applicable") counts.na += 1;
      if (["Conformity", "Opportunity for Improvement", "Minor Nonconformity", "Major Nonconformity"].includes(row.audit_result)) {
        counts.audited += 1;
        counts.scored += 1;
        counts.scoreSum += Number(row.score || 0);
      }
    });
    frm.doc.total_checklist_items = rows.length;
    frm.doc.audited_items = counts.audited;
    frm.doc.conformity_count = counts.conformity;
    frm.doc.ofi_count = counts.ofi;
    frm.doc.minor_nc_count = counts.minor;
    frm.doc.major_nc_count = counts.major;
    frm.doc.not_applicable_count = counts.na;
    frm.doc.overall_score = counts.scored ? (counts.scoreSum / counts.scored) : 0;
    ["audit_checklist", "total_checklist_items", "audited_items", "conformity_count", "ofi_count", "minor_nc_count", "major_nc_count", "not_applicable_count", "overall_score"].forEach(function (fieldname) {
      frm.refresh_field(fieldname);
    });
  }

  frappe.ui.form.on("Internal Audit", {
    refresh: calculate_summary,
    validate: calculate_summary,
    audit_checklist_add: calculate_summary,
    audit_checklist_remove: calculate_summary
  });

  frappe.ui.form.on("Internal Audit Checklist Item", {
    audit_result: function (frm, cdt, cdn) {
      const row = locals[cdt][cdn];
      apply_result(row);
      calculate_summary(frm);
    }
  });
})();

frappe.ui.form.on("Attendance Request", {
  before_save: async function (frm) {
    // Do not block approval or other workflow actions on existing requests.
    if (!frm.is_new() || !frm.doc.from_date) return;

    const settings = await frappe.db.get_doc("HR Settings", "HR Settings");
    const bypassRole = settings.custom_attendance_request_bypass_role || "HR User";
    const canBypassDeadline = frappe.session.user === "Administrator"
      || (bypassRole && frappe.user_roles.includes(bypassRole));

    const offset = cint(
      settings.custom_attendance_request_submission_offset_days || 0
    );
    const deadline = frappe.datetime.add_days(frm.doc.from_date, offset);
    const today = frappe.datetime.get_today();

    if (!canBypassDeadline && frappe.datetime.get_diff(today, deadline) > 0) {
      frappe.throw(__(
        "لا يمكن تقديم طلب الحضور بعد المهلة المحددة. آخر تاريخ مسموح للتقديم هو {0}.",
        [frappe.datetime.str_to_user(deadline)]
      ));
    }
  }
});

